actions.script:
// Attempt to pull real data from GL
def hasRealData = false

// Try to get P&L net income from GL
try {
    if (timePeriodId) {
        def plResult = ec.service.sync().name("mantle.ledger.LedgerReportServices.run#IncomeStatement")
                .parameters([organizationPartyId: organizationPartyId, timePeriodIdList: [timePeriodId]]).call()
        if (plResult?.netIncomeMap && plResult.netIncomeMap['ALL'] != 0) {
            hasRealData = true
        }
    }
} catch (Exception e) { /* fall through to demo */ }

if (!hasRealData) {
    showDemo = true
    periodName = periodName ?: "FY 2025-26"
}

// Operating Activities
netProfitBeforeTax = hasRealData ? 0.0 : 750000.00

operatingAdjustments = [
    [name: 'Depreciation & Amortization', amount: 60000.00],
    [name: 'Interest Expense', amount: 15000.00],
    [name: 'Interest Income', amount: -35000.00],
    [name: 'Loss on Sale of Assets', amount: 5000.00]
]

def adjTotal = 0.0
for (def a : operatingAdjustments) adjTotal += a.amount
cashFromOperations = netProfitBeforeTax + adjTotal

workingCapitalChanges = [
    [name: 'Decrease/(Increase) in Trade Receivables', amount: -200000.00],
    [name: 'Decrease/(Increase) in Inventories', amount: 120000.00],
    [name: 'Increase/(Decrease) in Trade Payables', amount: 170000.00],
    [name: 'Increase/(Decrease) in Other Current Liabilities', amount: 30000.00],
    [name: 'Income Tax Paid', amount: -187500.00]
]

def wcTotal = 0.0
for (def w : workingCapitalChanges) wcTotal += w.amount
netCashOperating = cashFromOperations + wcTotal

// Investing Activities
investingItems = [
    [name: 'Purchase of Property, Plant & Equipment', amount: -350000.00],
    [name: 'Sale of Investments', amount: 100000.00],
    [name: 'Interest Received', amount: 35000.00]
]

netCashInvesting = 0.0
for (def i : investingItems) netCashInvesting += i.amount

// Financing Activities
financingItems = [
    [name: 'Repayment of Long-Term Borrowings', amount: -300000.00],
    [name: 'Interest Paid', amount: -15000.00],
    [name: 'Dividends Paid', amount: -100000.00]
]

netCashFinancing = 0.0
for (def f : financingItems) netCashFinancing += f.amount

netCashChange = netCashOperating + netCashInvesting + netCashFinancing
openingCash = 1160000.00
closingCash = openingCash + netCashChange
